#include <bits/stdc++.h>
using namespace std;
class Solution {vector<vector<int>> adj;vector<int> tin,tout,xr;int timer;void dfs(int u,int p,vector<int>& nums){tin[u]=timer++;xr[u]=nums[u];for(int v:adj[u])if(v!=p){dfs(v,u,nums);xr[u]^=xr[v];}tout[u]=timer;}bool ancestor(int a,int b){return tin[a]<=tin[b]&&tout[b]<=tout[a];}public:int minimumScore(vector<int>& nums,vector<vector<int>>& edges){int n=nums.size();adj.assign(n,{});for(auto& e:edges){adj[e[0]].push_back(e[1]);adj[e[1]].push_back(e[0]);}tin.resize(n);tout.resize(n);xr.resize(n);timer=0;dfs(0,-1,nums);vector<int> nodes;for(int i=1;i<n;++i)nodes.push_back(i);int ans=INT_MAX,all=xr[0];for(int i=0;i<(int)nodes.size();++i)for(int j=i+1;j<(int)nodes.size();++j){int a=nodes[i],b=nodes[j],x,y,z;if(ancestor(a,b)){x=xr[b];y=xr[a]^xr[b];z=all^xr[a];}else if(ancestor(b,a)){x=xr[a];y=xr[b]^xr[a];z=all^xr[b];}else{x=xr[a];y=xr[b];z=all^x^y;}ans=min(ans,max({x,y,z})-min({x,y,z}));}return ans;}};
